import { readFile, writeFile, readdir } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const root = fileURLToPath(new URL('../src/agent/skills/minimax-h3/', import.meta.url));
const output = new URL('../src/agent/generated/h3Skills.ts', import.meta.url);
const metadata = JSON.parse(await readFile(new URL('../src/agent/skills/bundle-metadata.json', import.meta.url), 'utf8'));
async function files(directory) {
  return (await Promise.all((await readdir(directory, { withFileTypes: true })).map(entry => {
    const name = path.join(directory, entry.name);
    return entry.isDirectory() ? files(name) : [name];
  }))).flat();
}
const sources = new Map((await files(root)).map(file => ['/skills/' + path.relative(root, file).replaceAll('\\', '/'), file]));
// Metadata order is the released order; do not depend on filesystem or locale.
const keys = Object.keys(metadata);
if (keys.length !== sources.size || keys.some(key => !sources.has(key))) {
  throw new Error('Skill file set changed: update bundle-metadata.json explicitly.');
}
const entries = [];
const manifest = [];
for (const key of keys) {
  const { mimeType, created_at, modified_at, newline } = metadata[key];
  if (!['lf', 'crlf'].includes(newline)) throw new Error(`Invalid newline metadata: ${key}`);
  const normalized = (await readFile(sources.get(key), 'utf8')).replaceAll('\r\n', '\n');
  const content = newline === 'crlf' ? normalized.replaceAll('\n', '\r\n') : normalized;
  entries.push(`  ${JSON.stringify(key)}: { content: ${JSON.stringify(content)}, mimeType: ${JSON.stringify(mimeType)}, created_at: ${JSON.stringify(created_at)}, modified_at: ${JSON.stringify(modified_at)} },`);
  manifest.push(`  ${JSON.stringify(key)}: ${JSON.stringify(createHash('sha256').update(content).digest('hex'))},`);
}
const generated = `// Generated by scripts/generate-h3-skill-bundle.mjs. Do not edit.\n\nexport const officialH3Skills = {\n${entries.join('\n').replace(/,$/, '')}\n} as const;\n\nexport const officialH3SkillManifest = {\n${manifest.join('\n').replace(/,$/, '')}\n} as const;\n`;
if (process.argv.includes('--check')) {
  const current = (await readFile(output, 'utf8')).replaceAll('\r\n', '\n');
  if (current !== generated) {
    let offset = 0;
    while (current[offset] === generated[offset] && offset < current.length) offset++;
    throw new Error(`Skill bundle is stale at offset ${offset}: expected ${JSON.stringify(generated.slice(offset, offset + 60))}, got ${JSON.stringify(current.slice(offset, offset + 60))}. Run npm run generate:skills and review the diff.`);
  }
  console.log(`Skill bundle verified: ${keys.length} files; content, hashes and metadata unchanged.`);
} else {
  await writeFile(output, generated);
  console.log(`Generated ${keys.length} skill files.`);
}
